}

func (r *FileResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
 resp.Schema = schema.Schema{
  MarkdownDescription: "Synchronizes a single file to a remote host via SFTP.",
  Attributes: map[string]schema.Attribute{
   "source": schema.StringAttribute{
    MarkdownDescription: "Path to local source file",
    Required:            true,
   },
   "destination": schema.StringAttribute{
    MarkdownDescription: "Path on remote host",
    Required:            true,
   },
   "host": schema.StringAttribute{
    MarkdownDescription: "Remote host address",
    Required:            true,
   },
   "port": schema.Int64Attribute{
    MarkdownDescription: "SSH port (default: 22)",
    Optional:            true,
    Computed:            true,
    Default:             int64default.StaticInt64(22),
   },
   "user": schema.StringAttribute{
    MarkdownDescription: "SSH username",
    Required:            true,
   },
   "password": schema.StringAttribute{
    MarkdownDescription: "SSH password (prefer private_key)",
    Optional:            true,
    Sensitive:           true,
   },
   "private_key": schema.StringAttribute{
    MarkdownDescription: "SSH private key content",
    Optional:            true,
    Sensitive:           true,
   },
   "private_key_path": schema.StringAttribute{
    MarkdownDescription: "Path to SSH private key file",
    Optional:            true,
   },
   "source_hash": schema.StringAttribute{
    MarkdownDescription: "SHA256 hash of source file",
    Computed:            true,
    PlanModifiers: []planmodifier.String{
     stringplanmodifier.UseStateForUnknown(),
    },
   },
   "mode": schema.StringAttribute{
    MarkdownDescription: "File mode (default: 0644)",
    Optional:            true,
    Computed:            true,
    Default:             stringdefault.StaticString("0644"),
   },
   "id": schema.StringAttribute{
    Computed:            true,
    MarkdownDescription: "Resource identifier",
    PlanModifiers: []planmodifier.String{
     stringplanmodifier.UseStateForUnknown(),
    },
   },
   "bastion_host": schema.StringAttribute{
    MarkdownDescription: "Bastion/jump host address",
    Optional:            true,
   },
   "bastion_port": schema.Int64Attribute{
    MarkdownDescription: "Bastion SSH port (default: 22)",
    Optional:            true,
    Computed:            true,
    Default:             int64default.StaticInt64(22),
   },
   "bastion_user": schema.StringAttribute{
    MarkdownDescription: "Bastion SSH username",
    Optional:            true,
   },
   "bastion_password": schema.StringAttribute{
    MarkdownDescription: "Bastion SSH password",
    Optional:            true,
    Sensitive:           true,
   },
   "bastion_private_key": schema.StringAttribute{
    MarkdownDescription: "Bastion SSH private key content",
    Optional:            true,
    Sensitive:           true,
   },
   "bastion_private_key_path": schema.StringAttribute{
    MarkdownDescription: "Path to bastion SSH private key file",
    Optional:            true,
   },
  },
 }
}

func (r *FileResource) Configure(ctx context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
 // No provider-level client to configure
}

func (r *FileResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
 var data FileResourceModel

 resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Compute source hash
 sourceHash, err := hashFile(data.Source.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Hash Error", fmt.Sprintf("Unable to hash source file: %s", err))
  return
 }
 data.SourceHash = types.StringValue(sourceHash)

 // Build SSH config
 sshConfig, err := buildSSHConfig(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Parse file mode
 modeInt, err := strconv.ParseUint(data.Mode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid file mode: %s", err))
  return
 }

 // Upload file
 tflog.Debug(ctx, "Uploading file", map[string]interface{}{
  "source":      data.Source.ValueString(),
  "destination": data.Destination.ValueString(),
  "mode":        data.Mode.ValueString(),
 })

 err = client.Upload(ctx, data.Source.ValueString(), data.Destination.ValueString(), os.FileMode(modeInt))
 if err != nil {
  resp.Diagnostics.AddError("Upload Error", fmt.Sprintf("Unable to upload file: %s", err))
  return
 }

 // Set ID
 data.ID = types.StringValue(fmt.Sprintf("%s:%s", data.Host.ValueString(), data.Destination.ValueString()))

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *FileResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
 var data FileResourceModel

 resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Build SSH config
 sshConfig, err := buildSSHConfig(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Check if remote file exists
 exists, err := client.FileExists(ctx, data.Destination.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Remote Check Error", fmt.Sprintf("Unable to check remote file: %s", err))
  return
 }

 if !exists {
  // File was deleted externally, remove from state
  resp.State.RemoveResource(ctx)
  return
 }

 // Read remote file hash
 remoteHash, err := client.HashFile(ctx, data.Destination.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Remote Hash Error", fmt.Sprintf("Unable to hash remote file: %s", err))
  return
 }

 // Update the source hash in state to match remote
 // This allows terraform to detect drift
 data.SourceHash = types.StringValue(remoteHash)

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *FileResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
 var data FileResourceModel
 var state FileResourceModel

 resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
 resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Compute new source hash
 sourceHash, err := hashFile(data.Source.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Hash Error", fmt.Sprintf("Unable to hash source file: %s", err))
  return
 }
 data.SourceHash = types.StringValue(sourceHash)

 // Build SSH config
 sshConfig, err := buildSSHConfig(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Check for drift - get remote hash before update
 remoteHash, err := client.HashFile(ctx, data.Destination.ValueString())
 if err != nil && !strings.Contains(err.Error(), "file does not exist") {
  resp.Diagnostics.AddError("Remote Hash Error", fmt.Sprintf("Unable to hash remote file: %s", err))
  return
 }

 // If remote exists and doesn't match state, someone changed it externally
 if remoteHash != "" && remoteHash != state.SourceHash.ValueString() {
  resp.Diagnostics.AddError(
   "Remote file drift detected",
   fmt.Sprintf(
    "The remote file has been modified outside of Terraform.\n\n"+
     "Resource: filesync_file.%s\n"+
     "File: %s\n\n"+
     "Expected (from state): %s\n"+
     "Found (on remote):     %s\n\n"+
     "To resolve:\n"+
     "  - terraform refresh   # Accept remote as source of truth\n"+
     "  - terraform apply -replace=<resource>  # Force overwrite",
    data.ID.ValueString(),
    data.Destination.ValueString(),
    state.SourceHash.ValueString(),
    remoteHash,
   ),
  )
  return
 }

 // Parse file mode
 modeInt, err := strconv.ParseUint(data.Mode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid file mode: %s", err))
  return
 }

 // Upload file
 err = client.Upload(ctx, data.Source.ValueString(), data.Destination.ValueString(), os.FileMode(modeInt))
 if err != nil {
  resp.Diagnostics.AddError("Upload Error", fmt.Sprintf("Unable to upload file: %s", err))
  return
 }

 // Update ID if destination changed
 data.ID = types.StringValue(fmt.Sprintf("%s:%s", data.Host.ValueString(), data.Destination.ValueString()))

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *FileResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
 var data FileResourceModel

 resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Build SSH config
 sshConfig, err := buildSSHConfig(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Delete file
 err = client.Delete(ctx, data.Destination.ValueString())
 if err != nil {
  // If file doesn't exist, that's fine
  if !strings.Contains(err.Error(), "file does not exist") {
   resp.Diagnostics.AddError("Delete Error", fmt.Sprintf("Unable to delete file: %s", err))
   return
  }
 }
}

func (r *FileResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
 resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}

// hashFile computes SHA256 hash of a file
func hashFile(filePath string) (string, error) {
 // Resolve path
 absPath, err := filepath.Abs(filePath)
 if err != nil {
  return "", fmt.Errorf("failed to resolve path: %w", err)
 }

 file, err := os.Open(absPath)
 if err != nil {
  return "", fmt.Errorf("failed to open file: %w", err)
 }
 defer file.Close()

 hasher := sha256.New()
 if _, err := io.Copy(hasher, file); err != nil {
  return "", fmt.Errorf("failed to hash file: %w", err)
 }

 return hex.EncodeToString(hasher.Sum(nil)), nil
}
