func (r *DirectoryResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
 var data DirectoryResourceModel

 resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Get source directory path
 srcPath, err := filepath.Abs(data.Source.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Path Error", fmt.Sprintf("Unable to resolve source path: %s", err))
  return
 }

 // Build file manifest
 fileMap, err := buildFileManifest(srcPath)
 if err != nil {
  resp.Diagnostics.AddError("Manifest Error", fmt.Sprintf("Unable to build file manifest: %s", err))
  return
 }

 // Build SSH config from directory model
 sshConfig, err := buildSSHConfigFromDirectory(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Parse modes
 fileMode, err := strconv.ParseUint(data.Mode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid file mode: %s", err))
  return
 }
 dirMode, err := strconv.ParseUint(data.DirMode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid dir mode: %s", err))
  return
 }

 // Create destination directory
 err = client.MkdirAll(ctx, data.Destination.ValueString(), os.FileMode(dirMode))
 if err != nil {
  resp.Diagnostics.AddError("Directory Error", fmt.Sprintf("Unable to create destination directory: %s", err))
  return
 }

 // Upload each file
 for relPath := range fileMap {
  localPath := filepath.Join(srcPath, relPath)
  remotePath := filepath.Join(data.Destination.ValueString(), relPath)

  // Create parent directory if needed
  remoteDir := filepath.Dir(remotePath)
  err = client.MkdirAll(ctx, remoteDir, os.FileMode(dirMode))
  if err != nil {
   resp.Diagnostics.AddError("Directory Error", fmt.Sprintf("Unable to create directory %s: %s", remoteDir, err))
   return
  }

  tflog.Debug(ctx, "Uploading file", map[string]interface{}{
   "source":      localPath,
   "destination": remotePath,
  })

  err = client.Upload(ctx, localPath, remotePath, os.FileMode(fileMode))
  if err != nil {
   resp.Diagnostics.AddError("Upload Error", fmt.Sprintf("Unable to upload %s: %s", relPath, err))
   return
  }
 }

 // Convert fileMap to types.Map
 filesAttr := make(map[string]attr.Value)
 for k, v := range fileMap {
  filesAttr[k] = types.StringValue(v)
 }
 filesValue, diags := types.MapValue(types.StringType, filesAttr)
 resp.Diagnostics.Append(diags...)
 if resp.Diagnostics.HasError() {
  return
 }
 data.Files = filesValue

 // Set ID
 data.ID = types.StringValue(fmt.Sprintf("%s:%s", data.Host.ValueString(), data.Destination.ValueString()))

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *DirectoryResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
 var data DirectoryResourceModel

 resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Build SSH config from directory model
 sshConfig, err := buildSSHConfigFromDirectory(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Check if destination directory exists
 exists, err := client.DirExists(ctx, data.Destination.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Remote Check Error", fmt.Sprintf("Unable to check remote directory: %s", err))
  return
 }

 if !exists {
  resp.State.RemoveResource(ctx)
  return
 }

 // Get current state files map
 var stateFiles map[string]string
 if !data.Files.IsNull() {
  resp.Diagnostics.Append(data.Files.ElementsAs(ctx, &stateFiles, false)...)
  if resp.Diagnostics.HasError() {
   return
  }
 } else {
  stateFiles = make(map[string]string)
 }

 // Build remote file manifest
 remoteFiles := make(map[string]string)
 for relPath := range stateFiles {
  remotePath := filepath.Join(data.Destination.ValueString(), relPath)

  exists, err := client.FileExists(ctx, remotePath)
  if err != nil {
   resp.Diagnostics.AddError("Remote Check Error", fmt.Sprintf("Unable to check remote file %s: %s", remotePath, err))
   return
  }

  if exists {
   hash, err := client.HashFile(ctx, remotePath)
   if err != nil {
    resp.Diagnostics.AddError("Remote Hash Error", fmt.Sprintf("Unable to hash remote file %s: %s", remotePath, err))
    return
   }
   remoteFiles[relPath] = hash
  }
 }

 // Convert remoteFiles to types.Map
 filesAttr := make(map[string]attr.Value)
 for k, v := range remoteFiles {
  filesAttr[k] = types.StringValue(v)
 }
 filesValue, diags := types.MapValue(types.StringType, filesAttr)
 resp.Diagnostics.Append(diags...)
 if resp.Diagnostics.HasError() {
  return
 }
 data.Files = filesValue

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *DirectoryResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
 var data DirectoryResourceModel
 var state DirectoryResourceModel

 resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
 resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Get source directory path
 srcPath, err := filepath.Abs(data.Source.ValueString())
 if err != nil {
  resp.Diagnostics.AddError("Path Error", fmt.Sprintf("Unable to resolve source path: %s", err))
  return
 }

 // Build new file manifest
 newFileMap, err := buildFileManifest(srcPath)
 if err != nil {
  resp.Diagnostics.AddError("Manifest Error", fmt.Sprintf("Unable to build file manifest: %s", err))
  return
 }

 // Get state files
 var stateFiles map[string]string
 if !state.Files.IsNull() {
  resp.Diagnostics.Append(state.Files.ElementsAs(ctx, &stateFiles, false)...)
  if resp.Diagnostics.HasError() {
   return
  }
 } else {
  stateFiles = make(map[string]string)
 }

 // Build SSH config from directory model
 sshConfig, err := buildSSHConfigFromDirectory(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Parse modes
 fileMode, err := strconv.ParseUint(data.Mode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid file mode: %s", err))
  return
 }
 dirMode, err := strconv.ParseUint(data.DirMode.ValueString(), 8, 32)
 if err != nil {
  resp.Diagnostics.AddError("Mode Error", fmt.Sprintf("Invalid dir mode: %s", err))
  return
 }

 // Check for drift and upload changed files
 var driftedFiles []string
 for relPath, newHash := range newFileMap {
  remotePath := filepath.Join(data.Destination.ValueString(), relPath)

  // Check if file exists in state
  stateHash, inState := stateFiles[relPath]

  // Check remote hash
  remoteHash, err := client.HashFile(ctx, remotePath)
  if err != nil && !strings.Contains(err.Error(), "file does not exist") {
   resp.Diagnostics.AddError("Remote Hash Error", fmt.Sprintf("Unable to hash remote file %s: %s", remotePath, err))
   return
  }

  // Check for drift: file existed in state but remote differs from state
  if inState && remoteHash != "" && remoteHash != stateHash {
   driftedFiles = append(driftedFiles, fmt.Sprintf("  - %s (expected: %s, found: %s)", relPath, stateHash[:8], remoteHash[:8]))
  }

  // Upload if new or changed
  if newHash != stateHash || remoteHash != stateHash {
   localPath := filepath.Join(srcPath, relPath)

   // Create parent directory
   remoteDir := filepath.Dir(remotePath)
   err = client.MkdirAll(ctx, remoteDir, os.FileMode(dirMode))
   if err != nil {
    resp.Diagnostics.AddError("Directory Error", fmt.Sprintf("Unable to create directory %s: %s", remoteDir, err))
    return
   }

   tflog.Debug(ctx, "Uploading file", map[string]interface{}{
    "source":      localPath,
    "destination": remotePath,
   })

   err = client.Upload(ctx, localPath, remotePath, os.FileMode(fileMode))
   if err != nil {
    resp.Diagnostics.AddError("Upload Error", fmt.Sprintf("Unable to upload %s: %s", relPath, err))
    return
   }
  }
 }

 // Report drift if any
 if len(driftedFiles) > 0 {
  sort.Strings(driftedFiles)
  resp.Diagnostics.AddWarning(
   "Remote file drift detected",
   fmt.Sprintf(
    "The following remote files were modified outside of Terraform:\n%s\n\n"+
     "Files have been overwritten with local versions.",
    strings.Join(driftedFiles, "\n"),
   ),
  )
 }

 // Delete files that no longer exist locally
 for relPath := range stateFiles {
  if _, exists := newFileMap[relPath]; !exists {
   remotePath := filepath.Join(data.Destination.ValueString(), relPath)
   err = client.Delete(ctx, remotePath)
   if err != nil && !strings.Contains(err.Error(), "file does not exist") {
    resp.Diagnostics.AddError("Delete Error", fmt.Sprintf("Unable to delete %s: %s", relPath, err))
    return
   }
  }
 }

 // Convert newFileMap to types.Map
 filesAttr := make(map[string]attr.Value)
 for k, v := range newFileMap {
  filesAttr[k] = types.StringValue(v)
 }
 filesValue, diags := types.MapValue(types.StringType, filesAttr)
 resp.Diagnostics.Append(diags...)
 if resp.Diagnostics.HasError() {
  return
 }
 data.Files = filesValue

 // Update ID
 data.ID = types.StringValue(fmt.Sprintf("%s:%s", data.Host.ValueString(), data.Destination.ValueString()))

 resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *DirectoryResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
 var data DirectoryResourceModel

 resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
 if resp.Diagnostics.HasError() {
  return
 }

 // Build SSH config from directory model
 sshConfig, err := buildSSHConfigFromDirectory(&data)
 if err != nil {
  resp.Diagnostics.AddError("SSH Config Error", err.Error())
  return
 }

 // Create SFTP client
 client, err := gosftp.NewClient(ctx, sshConfig)
 if err != nil {
  resp.Diagnostics.AddError("SFTP Connection Error", fmt.Sprintf("Unable to connect to host: %s", err))
  return
 }
 defer client.Close()

 // Get state files
 var stateFiles map[string]string
 if !data.Files.IsNull() {
  resp.Diagnostics.Append(data.Files.ElementsAs(ctx, &stateFiles, false)...)
  if resp.Diagnostics.HasError() {
   return
  }
 } else {
  stateFiles = make(map[string]string)
 }

 // Delete each file we manage
 for relPath := range stateFiles {
  remotePath := filepath.Join(data.Destination.ValueString(), relPath)
  err = client.Delete(ctx, remotePath)
  if err != nil && !strings.Contains(err.Error(), "file does not exist") {
   tflog.Warn(ctx, "Unable to delete file", map[string]interface{}{
    "path":  remotePath,
    "error": err.Error(),
   })
  }
 }

 // Try to remove the directory (will fail if not empty, which is fine)
 err = client.RemoveDirectory(ctx, data.Destination.ValueString())
 if err != nil {
  tflog.Debug(ctx, "Unable to remove directory (may contain unmanaged files)", map[string]interface{}{
   "path":  data.Destination.ValueString(),
   "error": err.Error(),
  })
 }
}

func (r *DirectoryResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
 resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}

// buildFileManifest walks a directory and returns a map of relative paths to their hashes
func buildFileManifest(srcPath string) (map[string]string, error) {
 fileMap := make(map[string]string)

 err := filepath.Walk(srcPath, func(path string, info os.FileInfo, err error) error {
  if err != nil {
   return err
  }

  if info.IsDir() {
   return nil
  }

  relPath, err := filepath.Rel(srcPath, path)
  if err != nil {
   return err
  }

  hash, err := hashFileForManifest(path)
  if err != nil {
   return err
  }

  fileMap[relPath] = hash
  return nil
 })

 return fileMap, err
}

// hashFileForManifest computes SHA256 hash of a file
func hashFileForManifest(filePath string) (string, error) {
 file, err := os.Open(filePath)
 if err != nil {
  return "", err
 }
 defer file.Close()

 hasher := sha256.New()
 if _, err := io.Copy(hasher, file); err != nil {
  return "", err
 }

 return hex.EncodeToString(hasher.Sum(nil)), nil
}
