package diff

import (
 "fmt"
 "strings"
)

// UnifiedDiff generates a simple unified diff output for displaying file drift
func UnifiedDiff(expected, actual, filename string) string {
 var sb strings.Builder

 sb.WriteString(fmt.Sprintf("--- a/%s (expected from state)\n", filename))
 sb.WriteString(fmt.Sprintf("+++ b/%s (found on remote)\n", filename))
 sb.WriteString("@@ -1,1 +1,1 @@\n")
 sb.WriteString(fmt.Sprintf("-%s\n", expected))
 sb.WriteString(fmt.Sprintf("+%s\n", actual))

 return sb.String()
}
