type sshContainer struct {
 container testcontainers.Container
 host      string
 port      string
}

func setupSSHContainer(t *testing.T) *sshContainer {
 ctx := context.Background()

 req := testcontainers.ContainerRequest{
  Image:        "lscr.io/linuxserver/openssh-server:latest",
  ExposedPorts: []string{"2222/tcp"},
  Env: map[string]string{
   "PUID":            "1000",
   "PGID":            "1000",
   "USER_NAME":       "testuser",
   "USER_PASSWORD":   "testpass",
   "PASSWORD_ACCESS": "true",
  },
  WaitingFor: wait.ForLog("Server listening on").WithStartupTimeout(60 * time.Second),
 }

 container, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
  ContainerRequest: req,
  Started:          true,
 })
 if err != nil {
  t.Fatalf("Failed to start container: %v", err)
 }

 host, err := container.Host(ctx)
 if err != nil {
  t.Fatalf("Failed to get container host: %v", err)
 }

 mappedPort, err := container.MappedPort(ctx, "2222")
 if err != nil {
  t.Fatalf("Failed to get container port: %v", err)
 }

 // Give SSH server a moment to fully initialize
 time.Sleep(2 * time.Second)

 return &sshContainer{
  container: container,
  host:      host,
  port:      mappedPort.Port(),
 }
}

func (s *sshContainer) cleanup(t *testing.T) {
 if err := s.container.Terminate(context.Background()); err != nil {
  t.Logf("Warning: failed to terminate container: %v", err)
 }
}

