func TestAccFileResource_drift(t *testing.T) {
 if os.Getenv("TF_ACC") == "" {
  t.Skip("Acceptance tests skipped unless TF_ACC is set")
 }

 ssh := setupSSHContainer(t)
 defer ssh.cleanup(t)

 tmpDir := t.TempDir()
 testFilePath := filepath.Join(tmpDir, "test.txt")
 testContent := "Original content"

 if err := os.WriteFile(testFilePath, []byte(testContent), 0644); err != nil {
  t.Fatalf("Failed to create test file: %v", err)
 }

 resource.Test(t, resource.TestCase{
  ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
  Steps: []resource.TestStep{
   // Step 1: Create the file
   {
    Config: fmt.Sprintf(`
resource "filesync_file" "test" {
  source      = %q
  destination = "/config/drift-test.txt"
  host        = %q
  port        = %s
  user        = "testuser"
  password    = "testpass"
}
`, testFilePath, ssh.host, ssh.port),
   },
   // Step 2: Modify file remotely, then refresh to pick up drift
   {
    PreConfig: func() {
     // Modify file on remote
     ctx := context.Background()
     client, err := gosftp.NewClient(ctx, &gosftp.Config{
      Host:     ssh.host,
      Port:     2222,
      User:     "testuser",
      Password: "testpass",
     })
     if err != nil {
      t.Fatalf("Failed to create SFTP client: %v", err)
     }
     defer client.Close()

     // Write different content directly to remote
     modifiedPath := filepath.Join(tmpDir, "modified.txt")
     if err := os.WriteFile(modifiedPath, []byte("Modified remotely!"), 0644); err != nil {
      t.Fatalf("Failed to create modified file: %v", err)
     }
     if err := client.Upload(ctx, modifiedPath, "/config/drift-test.txt", 0644); err != nil {
      t.Fatalf("Failed to upload modified file: %v", err)
     }
    },
    Config: fmt.Sprintf(`
resource "filesync_file" "test" {
  source      = %q
  destination = "/config/drift-test.txt"
  host        = %q
  port        = %s
  user        = "testuser"
  password    = "testpass"
}
`, testFilePath, ssh.host, ssh.port),
    // Refresh will update state with remote hash, showing drift
    RefreshState: true,
   },
  },
 })
}
